import { describe, test, expect, vi } from 'vitest';
import { getPriceData } from '@salesforce/retail-react-app/app/utils/product-utils';
import {
  selectProductListCard,
  selectGalleryImages,
  selectSizeChipValues,
  resolveOrderableVariant,
  resolveRepresentativeColour,
} from './productListCardMapper';

const formatPrice = vi.fn((amount: number, currency: string) => `${currency} ${amount.toFixed(2)}`);

const baseHit = {
  productId: 'prod-1',
  productName: 'Natura Mini Dress',
  price: 595,
  currency: 'USD',
  image: { link: 'https://example.com/primary.jpg', alt: 'Natura Mini Dress' },
};

// Mirrors the confirmed live shape of a real 2-colour product (`ZWNEWPRD04`, colours BLK/TAN,
// each with its own separate, explicitly-tagged `imageGroups` entry at viewType: medium) --
// see productListCardMapper.ts's own `resolveRepresentativeColour`/`selectColourScopedImages`
// docblocks (plan addendum §7, step C1, 2026-09-09). BLK is deliberately rigged with MORE images
// than TAN even though TAN is the represented (correct) colour -- proving a test built on this
// fixture only passes because the fix reads representedProduct/variants, never because the
// "right" colour happens to also have the most images.
const MULTI_COLOUR_HIT = {
  ...baseHit,
  productId: 'ZWNEWPRD04',
  representedProduct: { id: 'ZWNEWPRD04TAN0' },
  variants: [
    { productId: 'ZWNEWPRD04BLK0', variationValues: { color: 'BLK' } },
    { productId: 'ZWNEWPRD04TAN0', variationValues: { color: 'TAN' } },
  ],
  imageGroups: [
    {
      viewType: 'medium',
      variationAttributes: [{ id: 'color', values: [{ value: 'BLK' }] }],
      images: [
        { link: 'blk-1.jpg', alt: 'WRONG COLOUR -- MUST NOT BE PICKED' },
        { link: 'blk-2.jpg', alt: 'WRONG COLOUR -- MUST NOT BE PICKED' },
        { link: 'blk-3.jpg', alt: 'WRONG COLOUR -- MUST NOT BE PICKED' },
        { link: 'blk-4.jpg', alt: 'WRONG COLOUR -- MUST NOT BE PICKED' },
      ],
    },
    {
      viewType: 'medium',
      variationAttributes: [{ id: 'color', values: [{ value: 'TAN' }] }],
      images: [
        { link: 'tan-1.jpg', alt: 'Cascade Midi Dress, Tan, front' },
        { link: 'tan-2.jpg', alt: 'Cascade Midi Dress, Tan, side' },
        { link: 'tan-3.jpg', alt: 'Cascade Midi Dress, Tan, back' },
      ],
    },
  ],
};

describe('selectProductListCard', () => {
  test('returns null when the hit has no product name', () => {
    expect(selectProductListCard({ ...baseHit, productName: undefined }, formatPrice)).toBeNull();
  });

  test('returns null when the hit has no usable image', () => {
    expect(selectProductListCard({ ...baseHit, image: undefined }, formatPrice)).toBeNull();
  });

  test('maps a real hit to plp ZimmProductCardProps', () => {
    const result = selectProductListCard(baseHit, formatPrice);
    expect(result).toEqual({
      id: 'prod-1',
      href: '/product/prod-1',
      name: 'Natura Mini Dress',
      headingLevel: 'h3',
      primaryImage: { src: 'https://example.com/primary.jpg', alt: 'Natura Mini Dress' },
      // baseHit has no imageGroups at all, so the colour+viewType-scoped array is empty --
      // hoverImage/primaryImageFallbacks gracefully absent, same as images (2026-09-09 addendum).
      hoverImage: undefined,
      primaryImageFallbacks: [],
      images: undefined,
      currentPrice: 'USD 595.00',
      originalPrice: undefined,
      isUnavailable: false,
      badge: undefined,
      variation: 'plp',
      sizeChipValues: [],
    });
  });

  test('uses disBaseLink over link when both are present', () => {
    const hit = { ...baseHit, image: { link: 'fallback.jpg', disBaseLink: 'preferred.jpg', alt: 'x' } };
    expect(selectProductListCard(hit, formatPrice)?.primaryImage.src).toBe('preferred.jpg');
  });

  // Changed 2026-09-08 (was/now pricing fix): `currentPrice` now comes from `getPriceData`, not
  // a direct read of `hit.price` — and base SFCC's own `findLowestPrice` (product-utils.js:280-
  // 281) deliberately resolves "no price found at all" to `0`, not `undefined` ("we re[s]et the
  // value to 0 as minPrice to be able to use this value on UI" — its own comment). So a hit with
  // no price and no tieredPrices renders "$0.00", not a blank price — confirmed by reading that
  // function directly, not assumed. This replaces the old premise (`hit.price` read directly,
  // `undefined` in → `undefined` out), which no longer describes what the code does.
  test('resolves to a real $0.00 (base SFCC behaviour), not undefined, when there is no price data at all', () => {
    const hit = { ...baseHit, price: undefined };
    expect(selectProductListCard(hit, formatPrice)?.currentPrice).toBe('USD 0.00');
  });

  test('marks isUnavailable true when orderable is false', () => {
    expect(selectProductListCard({ ...baseHit, orderable: false }, formatPrice)?.isUnavailable).toBe(true);
  });

  // Was/now pricing (2026-09-08 fix) — closes the previously-confirmed gap: `originalPrice` used
  // to be hardcoded `undefined` regardless of data. Both fixtures cross-check against a real,
  // independent `getPriceData` call, not a hand-picked expectation — same "G1" doctrine
  // `recentlyViewedFullHistoryCard.test.ts`'s own equivalent tests already document.
  describe('was/now pricing', () => {
    const ON_SALE_HIT = {
      ...baseHit,
      price: 500,
      tieredPrices: [
        { price: 500, quantity: 1 },
        { price: 650, quantity: 1 },
      ],
    };

    test('originalPrice is the real "was" price when the hit is genuinely on sale', () => {
      const independent = getPriceData(ON_SALE_HIT);
      expect(independent.isOnSale).toBe(true);

      const card = selectProductListCard(ON_SALE_HIT, formatPrice);
      expect(card?.currentPrice).toBe('USD 500.00');
      expect(card?.originalPrice).toBe('USD 650.00');
    });

    test('originalPrice stays undefined — never equal to currentPrice — when the hit is not on sale', () => {
      // Identical price/listPrice (both 595) -- getPriceData's isOnSale is `currentPrice < listPrice`,
      // false when they're equal. A not-on-sale hit must never render a crossed-out price
      // identical to its current one.
      const notOnSaleHit = { ...baseHit, tieredPrices: [{ price: 595, quantity: 1 }] };
      const independent = getPriceData(notOnSaleHit);
      expect(independent.isOnSale).toBe(false);

      const card = selectProductListCard(notOnSaleHit, formatPrice);
      expect(card?.originalPrice).toBeUndefined();
      expect(card?.currentPrice).toBe('USD 595.00');
    });
  });

  test('maps the single highest-priority badge when c_productBadges is present', () => {
    const hit = { ...baseHit, c_productBadges: [{ productBadge: 'Runway' }, { productBadge: 'New In' }] };
    expect(selectProductListCard(hit, formatPrice)?.badge).toBe('Runway');
  });

  test('leaves badge undefined when c_productBadges is absent', () => {
    expect(selectProductListCard(baseHit, formatPrice)?.badge).toBeUndefined();
  });
});

describe('resolveOrderableVariant (2026-09-08, Gap 3 fix: size-aware Add to Bag)', () => {
  const hitWithVariants = {
    ...baseHit,
    variants: [
      { productId: 'prod-1-S', price: 595, orderable: true, variationValues: { size: 'S' } },
      { productId: 'prod-1-M', price: 595, orderable: false, variationValues: { size: 'M' } },
      { productId: 'prod-1-L', price: 650, orderable: true, variationValues: { size: 'L' } },
    ],
  };

  test('resolves the real variant productId and price for the selected size', () => {
    expect(resolveOrderableVariant(hitWithVariants, 'L')).toEqual({
      productId: 'prod-1-L',
      price: 650,
      orderable: true,
    });
  });

  test('reports orderable: false for a genuinely unorderable size, rather than dropping it', () => {
    expect(resolveOrderableVariant(hitWithVariants, 'M')).toEqual({
      productId: 'prod-1-M',
      price: 595,
      orderable: false,
    });
  });

  test('returns null when the size value matches no real variant', () => {
    expect(resolveOrderableVariant(hitWithVariants, 'XL')).toBeNull();
  });

  test('returns null when the hit has no variants array at all', () => {
    expect(resolveOrderableVariant(baseHit, 'S')).toBeNull();
  });
});

describe('resolveRepresentativeColour', () => {
  test("resolves the represented variant's colour", () => {
    expect(resolveRepresentativeColour(MULTI_COLOUR_HIT)).toBe('TAN');
  });

  test('returns undefined when there is no representedProduct', () => {
    const hit = { ...MULTI_COLOUR_HIT, representedProduct: undefined };
    expect(resolveRepresentativeColour(hit)).toBeUndefined();
  });

  test('returns undefined when there is no variants array at all', () => {
    const hit = { ...MULTI_COLOUR_HIT, variants: undefined };
    expect(resolveRepresentativeColour(hit)).toBeUndefined();
  });

  test('returns undefined when representedProduct.id matches no variant', () => {
    const hit = { ...MULTI_COLOUR_HIT, representedProduct: { id: 'ZWNEWPRD04-NO-MATCH' } };
    expect(resolveRepresentativeColour(hit)).toBeUndefined();
  });
});

describe('selectGalleryImages', () => {
  test('returns undefined when there are no image groups', () => {
    expect(selectGalleryImages({ ...baseHit, imageGroups: undefined })).toBeUndefined();
  });

  test('returns undefined when the matching viewType: medium group has only 1 image', () => {
    const hit = {
      ...baseHit,
      imageGroups: [
        { viewType: 'medium', images: [{ link: 'a.jpg', alt: 'Only image' }] },
        { viewType: 'swatch', images: [{ link: 'b.jpg', alt: 'swatch' }] },
      ],
    };
    expect(selectGalleryImages(hit)).toBeUndefined();
  });

  // Replaces the old "picks the image group with the most images" test -- picking irrespective
  // of viewType is exactly the confirmed live defect this addendum removes (plan addendum §7,
  // step C1, 2026-09-09). This fixture has no representedProduct/variants at all, so
  // resolveRepresentativeColour must return undefined and the mapper must still scope to
  // viewType: 'medium' alone -- never fall back to the old fully-unscoped "biggest group
  // anywhere" pick. The 'large' group has MORE images (4) than the 'medium' group (2); under the
  // old unscoped logic 'large' would have won -- asserting 'medium' wins here proves it no longer
  // does.
  test('scopes to viewType: medium alone when no colour resolves, ignoring other viewTypes even when they have more images', () => {
    const hit = {
      ...baseHit,
      representedProduct: undefined,
      variants: undefined,
      imageGroups: [
        {
          viewType: 'large',
          images: [
            { link: 'large-1.jpg', alt: 'WRONG VIEWTYPE -- MUST NOT BE PICKED' },
            { link: 'large-2.jpg', alt: 'WRONG VIEWTYPE -- MUST NOT BE PICKED' },
            { link: 'large-3.jpg', alt: 'WRONG VIEWTYPE -- MUST NOT BE PICKED' },
            { link: 'large-4.jpg', alt: 'WRONG VIEWTYPE -- MUST NOT BE PICKED' },
          ],
        },
        {
          viewType: 'medium',
          images: [
            { link: 'medium-1.jpg', alt: 'Natura Mini Dress, front' },
            { link: 'medium-2.jpg', alt: 'Natura Mini Dress, back' },
          ],
        },
      ],
    };
    expect(selectGalleryImages(hit)).toEqual([
      { src: 'medium-1.jpg', alt: 'Natura Mini Dress, front' },
      { src: 'medium-2.jpg', alt: 'Natura Mini Dress, back' },
    ]);
  });

  // The direct colour-isolation proof requested by the addendum: the wrong colour (BLK) has MORE
  // images (4) than the right one (TAN, 3) -- if this passed under the OLD "most images wins, no
  // colour/viewType filter" logic it would return the BLK images instead. Confirmed to actually
  // fail against that old logic before this fix landed -- see the implementation report for the
  // real before/after `npm run test` output (this codebase's own "make it fail on purpose first"
  // discipline, restated throughout the build plan).
  test('gallery only ever contains the represented colour, even though the wrong colour has more images', () => {
    expect(selectGalleryImages(MULTI_COLOUR_HIT)).toEqual([
      { src: 'tan-1.jpg', alt: 'Cascade Midi Dress, Tan, front' },
      { src: 'tan-2.jpg', alt: 'Cascade Midi Dress, Tan, side' },
      { src: 'tan-3.jpg', alt: 'Cascade Midi Dress, Tan, back' },
    ]);
  });
});

describe('hoverImage / primaryImageFallbacks (colour-scoped image array, 2026-09-09 addendum)', () => {
  test('hoverImage is index [1] of the same colour-scoped array selectGalleryImages reads', () => {
    const card = selectProductListCard(MULTI_COLOUR_HIT, formatPrice);
    expect(card?.hoverImage).toEqual({ src: 'tan-2.jpg', alt: 'Cascade Midi Dress, Tan, side' });
  });

  test('primaryImageFallbacks is the rest of that array after hoverImage, independent of hit.image', () => {
    const card = selectProductListCard(MULTI_COLOUR_HIT, formatPrice);
    expect(card?.primaryImageFallbacks).toEqual([{ src: 'tan-3.jpg', alt: 'Cascade Midi Dress, Tan, back' }]);
    // hit.image (primaryImage) is untouched by this addendum -- still baseHit's own image, never
    // derived from the colour-scoped array.
    expect(card?.primaryImage).toEqual({ src: 'https://example.com/primary.jpg', alt: 'Natura Mini Dress' });
  });

  test('both are empty/undefined, not throwing, when there are no image groups at all', () => {
    const card = selectProductListCard({ ...baseHit, imageGroups: undefined }, formatPrice);
    expect(card?.hoverImage).toBeUndefined();
    expect(card?.primaryImageFallbacks).toEqual([]);
  });

  test('both are empty/undefined, not throwing, when the colour-scoped array has exactly 1 image', () => {
    const hit = {
      ...baseHit,
      imageGroups: [{ viewType: 'medium', images: [{ link: 'only.jpg', alt: 'Only image' }] }],
    };
    const card = selectProductListCard(hit, formatPrice);
    expect(card?.hoverImage).toBeUndefined();
    expect(card?.primaryImageFallbacks).toEqual([]);
    expect(card?.images).toBeUndefined();
  });
});

describe('selectSizeChipValues', () => {
  test('returns an empty array when there is no size variation attribute', () => {
    expect(selectSizeChipValues({ ...baseHit, variationAttributes: undefined })).toEqual([]);
  });

  test('maps size attribute values to chip values, disabled from orderable', () => {
    const hit = {
      ...baseHit,
      variationAttributes: [
        {
          id: 'size',
          name: 'Size',
          values: [
            { value: 'xs', name: 'XS', orderable: true },
            { value: 's', name: 'S', orderable: false },
          ],
        },
        { id: 'color', name: 'Colour', values: [{ value: 'black', name: 'Black', orderable: true }] },
      ],
    };
    expect(selectSizeChipValues(hit)).toEqual([
      { value: 'xs', label: 'XS', isDisabled: false },
      { value: 's', label: 'S', isDisabled: true },
    ]);
  });

  test('falls back to the raw value as label when name is missing', () => {
    const hit = {
      ...baseHit,
      variationAttributes: [{ id: 'size', values: [{ value: 'm', orderable: true }] }],
    };
    expect(selectSizeChipValues(hit)).toEqual([{ value: 'm', label: 'm', isDisabled: false }]);
  });
});

